#ifndef CHDB_MODULE_H
#define CHDB_MODULE_H

#include "postgres.h"

#include "fmgr.h"

#include "version.h" /* Generated by Makefile. */

/*
 * The magic block every module of the distribution exports, named and
 * versioned where the server can report it. PG_MODULE_MAGIC_EXT arrived in
 * PostgreSQL 18; older servers take the plain block.
 */
#ifdef PG_MODULE_MAGIC_EXT
#define CHDB_MODULE_MAGIC(modname)                                                     \
    PG_MODULE_MAGIC_EXT(.name = modname, .version = PGCHCB_VERSION)
#else
#define CHDB_MODULE_MAGIC(modname) PG_MODULE_MAGIC
#endif

#endif /* CHDB_MODULE_H */
